+type Message struct { Role string `json:"role"`; Content string `json:"content"` }
+type Planner interface { Next(context.Context,[]Message)(Action,Usage,error) }
+type Model struct{ Base,Key,Name,Provider string; Client *http.Client; InputRate,OutputRate *float64 }
+func NewModel()*Model{
+ rate:=func(k string)*float64{v,err:=strconv.ParseFloat(os.Getenv(k),64);if err!=nil||v<0{return nil};return &v}
+ return &Model{Base:strings.TrimRight(config.Env("MODEL_BASE_URL",os.Getenv("APERTUS_API_BASE_URL")),"/"),Key:config.Env("MODEL_API_KEY",os.Getenv("APERTUS_API_KEY")),Name:config.Env("MODEL_NAME",os.Getenv("APERTUS_MODEL")),Provider:config.Env("MODEL_PROVIDER","publicai"),Client:&http.Client{Timeout:45*time.Second,CheckRedirect:func(*http.Request,[]*http.Request)error{return http.ErrUseLastResponse}},InputRate:rate("MODEL_INPUT_USD_PER_MILLION"),OutputRate:rate("MODEL_OUTPUT_USD_PER_MILLION")}
+}
+func(m *Model)Ready()bool{return m.Key!=""&&m.Base!=""&&m.Name!=""}
+func(m *Model)Next(ctx context.Context,messages []Message)(Action,Usage,error){
+ var action Action;var usage Usage
+ nlMessages:=make([]neatlogs.LLMMessage,len(messages));for i,msg:=range messages{nlMessages[i]=neatlogs.LLMMessage{Role:msg.Role,Content:msg.Content}}
+ ctx,span:=neatlogs.StartLLMSpan(ctx,neatlogs.LLMCallOptions{Provider:m.Provider,Model:m.Name,Messages:nlMessages,MaxTokens:450});defer span.End()
+ body,_:=json.Marshal(map[string]any{"model":m.Name,"messages":messages,"max_tokens":450,"temperature":0.1,"response_format":map[string]string{"type":"json_object"}})
+ request,err:=http.NewRequestWithContext(ctx,"POST",m.Base+"/chat/completions",bytes.NewReader(body));if err!=nil{return action,usage,errors.New("invalid model endpoint")}
+ request.Header.Set("Content-Type","application/json");request.Header.Set("Authorization","Bearer "+m.Key)
+ response,err:=m.Client.Do(request);if err!=nil{safe:=errors.New("model request failed or timed out");span.SetError(safe);return action,usage,safe};defer response.Body.Close()
+ if response.StatusCode!=200{err=fmt.Errorf("model HTTP %d",response.StatusCode);span.SetError(err);return action,usage,err}
+ var result struct{Choices []struct{Message Message `json:"message"`; Finish string `json:"finish_reason"`} `json:"choices"`; Usage struct{Input int `json:"prompt_tokens"`;Output int `json:"completion_tokens"`;Total int `json:"total_tokens"`} `json:"usage"`;Model string `json:"model"`;ID string `json:"id"`}
+ if err=json.NewDecoder(io.LimitReader(response.Body,1<<20)).Decode(&result);err!=nil{return action,usage,errors.New("invalid model response")}
+ usage.Input=result.Usage.Input;usage.Output=result.Usage.Output
