+)
+
+// A visible, dedicated browser profile lets the user authenticate directly.
+// Login credentials and cookies never pass through the API or model prompt.
+type marketSession struct {
+	environment string
+	ctx context.Context
+	cancel context.CancelFunc
+	allocCancel context.CancelFunc
+}
+
+var shopeeProduct = regexp.MustCompile(`(?:-i\.[0-9]+\.[0-9]+$|^/product/[0-9]+/[0-9]+/?$)`)
+
+func marketHome(environment string) string {
+	if environment == "shopee" { return "https://shopee.co.id/" }
+	if environment == "tokopedia" { return "https://www.tokopedia.com/" }
+	return ""
+}
+
+func validateTarget(environment, raw, base string) error {
+	if environment == "sandbox" {
+		if raw != "" && strings.TrimRight(raw, "/") != base+"/sandbox" { return errors.New("sandbox mode accepts only the local synthetic sandbox URL") }
+		return nil
+	}
+	if marketHome(environment) == "" { return errors.New("choose sandbox, shopee, or tokopedia") }
+	u, err := url.Parse(raw)
+	if err != nil || !marketPageAllowed(environment, raw) || u.RawPath != "" || u.Fragment != "" { return errors.New("enter a full HTTPS product URL for the selected marketplace") }
+	if environment == "shopee" && !shopeeProduct.MatchString(u.Path) { return errors.New("use a Shopee product URL ending in -i.shopID.itemID or /product/shopID/itemID") }
+	if environment == "tokopedia" {
+		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
+		reserved := map[string]bool{"login": true, "register": true, "cart": true, "checkout": true, "order": true, "payment": true, "discovery": true, "search": true, "help": true, "user": true, "settings": true, "account": true, "api": true}
+		if len(parts) != 2 || parts[0] == "" || parts[1] == "" || reserved[strings.ToLower(parts[0])] || parts[0] == "." || parts[0] == ".." || parts[1] == "." || parts[1] == ".." { return errors.New("use a Tokopedia product URL: https://www.tokopedia.com/shop/product") }
+	}
+	return nil
+}
+
+func marketPageAllowed(environment, raw string) bool {
+	u, err := url.Parse(raw)
+	if err != nil || u.Scheme != "https" || u.User != nil || u.Port() != "" { return false }
+	host := strings.ToLower(u.Hostname())
+	if environment == "shopee" { return host == "shopee.co.id" || host == "www.shopee.co.id" }
+	if environment == "tokopedia" { return host == "tokopedia.com" || host == "www.tokopedia.com" }
+	return false
+}
+
+func marketResourceAllowed(environment, raw, method string, document bool) bool {
+	u, err := url.Parse(raw)
+	if err != nil || u.Scheme != "https" || u.User != nil || u.Port() != "" { return false }
+	if document { return marketPageAllowed(environment, raw) && (method == "GET" || method == "HEAD") }
+	roots := []string{"tokopedia.com", "tokopedia.net"}
+	if environment == "shopee" { roots = []string{"shopee.co.id", "shopeemobile.com", "susercontent.com"} } else if environment != "tokopedia" { return false }
+	host := strings.ToLower(u.Hostname())
+	allowed := false
+	for _, root := range roots { if host == root || strings.HasSuffix(host, "."+root) { allowed = true } }
+	if !allowed { return false }
+	path := strings.ToLower(u.Path)
+	for _, term := range []string{"place_order", "placeorder", "create_order", "createorder", "/order/create", "/order/submit", "/payment", "/pay/", "/wallet", "/transfer"} { if strings.Contains(path, term) { return false } }
+	if method == "GET" || method == "HEAD" || method == "OPTIONS" { return true }
+	// Only the known Shopee cart/check-out preview routes may mutate during
+	// preparation. Unknown mutations (including opaque GraphQL) fail closed.
+	return environment == "shopee" && method == "POST" && strings.HasSuffix(host, "shopee.co.id") && (strings.HasPrefix(path, "/api/v4/cart/") || path == "/api/v4/checkout/get")
+}
+
+func (a *App) closeMarketSessionLocked() {
+	if a.marketSession != nil { a.marketSession.cancel(); a.marketSession.allocCancel(); a.marketSession = nil }
+}
+
+func (a *App) marketplaceRoutes(mux *http.ServeMux) {
+	mux.HandleFunc("GET /api/marketplaces/session", func(w http.ResponseWriter, r *http.Request) {
+		a.mu.Lock(); defer a.mu.Unlock()
+		state := map[string]any{"environment": "", "browser_open": false, "authentication": "not_checked", "mode": "prepare_checkout"}
+		if s := a.marketSession; s != nil && s.ctx.Err() == nil { state["environment"] = s.environment; state["browser_open"] = true }
+		writeJSON(w, 200, state)
+	})
+	mux.HandleFunc("POST /api/marketplaces/{environment}/connect", func(w http.ResponseWriter, r *http.Request) {
+		environment := r.PathValue("environment")
+		if marketHome(environment) == "" { writeError(w, 400, "unknown marketplace"); return }
+		a.mu.Lock(); defer a.mu.Unlock()
+		if a.activeID != "" { writeError(w, 409, "stop the active run before opening a marketplace browser"); return }
+		if s := a.marketSession; s != nil && s.environment == environment && s.ctx.Err() == nil {
+			checkCtx, cancel := context.WithTimeout(s.ctx, 2*time.Second)
+			var title string
+			err := chromedp.Run(checkCtx, chromedp.Title(&title)); cancel()
+			if err == nil { writeJSON(w, 200, map[string]string{"status": "browser_open", "authentication": "sign in directly in the browser"}); return }
+		}
+		a.closeMarketSessionLocked()
+		profile := filepath.Join(filepath.Dir(a.EvidenceDir), "tmp", "marketplace-profiles", environment)
+		if err := os.MkdirAll(profile, 0700); err != nil { writeError(w, 500, "cannot create private browser profile"); return }
+		opts := append([]chromedp.ExecAllocatorOption{}, chromedp.DefaultExecAllocatorOptions[:]...)
+		opts = append(opts, chromedp.Flag("headless", false), chromedp.UserDataDir(profile), chromedp.WindowSize(1280, 900))
+		if path := os.Getenv("CHROME_PATH"); path != "" { opts = append(opts, chromedp.ExecPath(path)) }
+		alloc, allocCancel := chromedp.NewExecAllocator(context.Background(), opts...)
+		ctx, cancel := chromedp.NewContext(alloc)
+		s := &marketSession{environment: environment, ctx: ctx, cancel: cancel, allocCancel: allocCancel}
+		startup, stop := context.WithTimeout(ctx, 12*time.Second)
+		err := chromedp.Run(startup, chromedp.Navigate(marketHome(environment)))
+		stop()
+		if err != nil { cancel(); allocCancel(); writeError(w, 503, "cannot open marketplace browser; check Chrome, connectivity, and GUI permissions"); return }
+		a.marketSession = s
+		writeJSON(w, 200, map[string]string{"status": "browser_open", "authentication": "sign in directly in the browser"})
+	})
+	mux.HandleFunc("POST /api/marketplaces/session/close", func(w http.ResponseWriter, r *http.Request) {
+		a.mu.Lock(); defer a.mu.Unlock()
+		if a.activeID != "" { writeError(w, 409, "stop the active run first"); return }
+		a.closeMarketSessionLocked()
