+
+func (a *App) executeMarketplace(ctx context.Context, run *Run) {
+	a.mu.Lock(); session := a.marketSession; a.mu.Unlock()
+	if session == nil { run.Status = "failed"; run.Reason = "Marketplace browser is not open"; return }
+	bctx, cancel := context.WithCancel(session.ctx)
+	stop := context.AfterFunc(ctx, cancel)
+	defer stop(); defer cancel()
+	// Turn interception off again before handing the browser back to the user.
+	defer func() { clean, end := context.WithTimeout(session.ctx, 2*time.Second); defer end(); _ = chromedp.Run(clean, fetch.Disable()) }()
+	chromedp.ListenTarget(bctx, func(event any) {
+		if e, ok := event.(*fetch.EventRequestPaused); ok {
+			go func() { _ = chromedp.Run(bctx, chromedp.ActionFunc(func(c context.Context) error {
+				if marketResourceAllowed(run.Environment, e.Request.URL, e.Request.Method, e.ResourceType == network.ResourceTypeDocument) { return fetch.ContinueRequest(e.RequestID).Do(c) }
