+// Tokopedia GraphQL is permitted only for read queries or explicit cart root
+// fields. Unknown mutations remain blocked, even if their operation is renamed.
+func marketGraphQLAllowed(raw, body string) bool {
+	u, err := url.Parse(raw)
+	if err != nil || u.Scheme != "https" || u.User != nil || u.Port() != "" || !(u.Hostname() == "tokopedia.com" || strings.HasSuffix(u.Hostname(), ".tokopedia.com")) || !strings.HasPrefix(u.Path, "/graphql") || len(body) > 65536 { return false }
+	type operation struct { Query string `json:"query"` }
+	var operations []operation
+	if strings.HasPrefix(strings.TrimSpace(body), "[") { if json.Unmarshal([]byte(body), &operations) != nil { return false } } else { var op operation; if json.Unmarshal([]byte(body), &op) != nil { return false }; operations = []operation{op} }
+	if len(operations) == 0 || len(operations) > 20 { return false }
+	for _, op := range operations {
+		query := strings.TrimSpace(op.Query)
+		if strings.HasPrefix(query, "query ") || strings.HasPrefix(query, "query(") || strings.HasPrefix(query, "query{") || strings.HasPrefix(query, "{") {
+			if regexp.MustCompile(`\b(mutation|subscription)\b`).MatchString(query) { return false }
+			continue
+		}
+		// A single cart mutation, without aliases, directives, variables containing
