+func retryAfter(value string,now time.Time)time.Duration {
+	if seconds,err:=strconv.ParseInt(value,10,32);err==nil&&seconds>0{return time.Duration(seconds)*time.Second}
+	if at,err:=http.ParseTime(value);err==nil&&at.After(now){return at.Sub(now)}
