+import "errors"
+
+// Structured output is opt-in per provider profile. Unsupported providers keep
+// JSON-object mode; never retry silently with weaker validation after rejection.
+func actionResponseFormat(mode string) (map[string]any, error) {
+	if mode == "" || mode == "json_object" {
+		return map[string]any{"type": "json_object"}, nil
+	}
+	if mode != "json_schema" {
+		return nil, errors.New("MODEL_RESPONSE_FORMAT must be json_object or json_schema")
